def text(x):
    if x is None:
        return ''
    if isinstance(x, list) or isinstance(x, tuple):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x)

def hasword(strin, word):
    s = ' ' + text(strin).lower() + ' '
    return bool(word and (' ' + word + ' ') in s)

def needverb(tt):
    if 'clean' in tt:
        return 'clean', 'sinkbasin'
    if 'heat' in tt:
        return 'heat', 'microwave'
    if 'cool' in tt:
        return 'cool', 'fridge'
    return '', ''

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', '')).lower()
    target = text(getv(ctx, 'task.target_type', '')).lower()
    dest = text(getv(ctx, 'task.destination_type', '')).lower()
    verb, tool = needverb(tt)
    if not verb:
        nb['transformed'] = True
        nb['ready_to_place'] = True
    act = text(getv(ctx, 'action.final_action', '') + ' ' + getv(ctx, 'action.normalized', '') + ' ' + getv(ctx, 'action.raw', '')).lower()
    obs = text(ctx.get('observation', '')).lower()
    inv = text(getv(ctx, 'world.inventory', '')).lower()
    if not verb:
        nb['transformed'] = True
        nb['ready_to_place'] = bool(target and hasword(act, target) and ('put ' in act or 'you put' in obs))
    if verb and target and hasword(act, target) and target in obs:
        if act.startswith(verb + ' ') and (not tool or tool in act):
            nb['transformed'] = True
            nb['ready_to_place'] = True
        elif ('you ' + verb in obs or 'is now ' + verb in obs) and (not tool or tool in obs):
            nb['transformed'] = True
            nb['ready_to_place'] = True
    if target and act.startswith('put ') and target in act and 'nothing happens' not in obs and 'cannot put' not in obs:
        nb['ready_to_place'] = False
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > int(nb.get('placed_count', 0)) and target and (not dest or hasword(act, dest) or hasword(act, target)) and 'nothing happens' not in obs and 'cannot put' not in obs:
        nb['placed_count'] = pc
        if verb and not nb.get('transformed'):
            nb['stage'] = 'transform'
        else:
            nb['stage'] = 'find_target'
    holding_target = bool(target and target in inv)
    holding_nonempty = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and 'empty' not in inv and 'none' not in inv)
    take_ready = False
    for a in ctx.get('admissible', []):
        al = text(a).lower()
        if target and al.startswith('take ') and target in al and ' from ' in al:
            take_ready = True
    if holding_nonempty and target and not holding_target:
        stage = 'wrong_inventory'
    elif holding_target and verb and not nb.get('transformed'):
        stage = 'transform'
    elif holding_target and dest and not nb.get('ready_to_place'):
        stage = 'go_destination'
    elif holding_target and dest and nb.get('ready_to_place'):
        stage = 'put_target'
    elif take_ready or hasword(obs, target) or hasword(obs, 'you see') or getv(ctx, 'world.target_found', False):
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['transform_verb'] = verb
    nb['transform_tool'] = tool
    return None

