def hook(ctx, nb):
    tt = nb.get('task_type', getv(ctx, 'task.task_type', ''))
    target = nb.get('target_type', getv(ctx, 'task.target_type', 'target'))
    dest = nb.get('destination_type', getv(ctx, 'task.destination_type', 'destination'))
    verb = nb.get('transform_verb', needverb(tt)[0])
    tool = nb.get('transform_tool', needverb(tt)[1])
    stage = nb.get('stage', 'find_target')
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You appear to be carrying a non-target item. Do not place it at the goal; put it back if needed, then search for the requested ' + target + '.'
    elif stage == 'transform' and verb and tool and target:
        msg = 'Before placing the ' + target + ', use the ' + verb + ' action at a ' + tool + '. Do not use a lamp for this step.'
    elif stage == 'take_target' and target:
        msg = 'A requested ' + target + ' is available here. Take the target instead of continuing an exhaustive search.'
    elif stage == 'put_target' and target and dest:
        msg = 'The ' + target + ' is ready. Use the put action for the ' + dest + ', not a nearby wrong receptacle.'
    elif stage == 'go_destination' and target and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' and place it there.'
    if not msg or msg == nb.get('last_hint'):
        return None
    nb['last_hint'] = msg
    return {'message': msg}

